410	func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
411		checkpointsCount, filesTouched, tokenUsage, err :=
412			s.reaggregateFromEntries(basePath, len(sessions), entries)
