28	// DiffTreeFileList returns the list of files changed between two commits using git diff-tree.
29	// For initial commits (commit1 is empty), use --root mode.
30	// repoDir is the path to the git repository working tree; the command runs in that directory.
31	func DiffTreeFileList(ctx context.Context, repoDir, commit1, commit2 string) ([]string, error) {
32		return diffTreeRaw(ctx, repoDir, commit1, commit2)
33	}
