```go
// ComputeFilesChangedHash computes a SHA256 hash of the given files' blob hashes
// at the specified commit. The hash is computed from sorted "filepath:blobhash" pairs,
// making it independent of input order and stable across rebases (same file content
// produces the same blob hash regardless of repo history).
//
// filePaths should be the files changed by the commit (from committedFileSet).
// commitHash is the commit whose tree contains the file blobs.
// Returns a 64-char hex SHA256 string.
//
// Uses a single `git ls-tree` call with all file paths to avoid O(N) subprocess
// invocations. PostCommit hooks run synchronously on every commit, so this matters.
func ComputeFilesChangedHash(ctx context.Context, repoDir, commitHash string, filePaths []string) (string, error) {
	if len(filePaths) == 0 {
		return "", nil
	}

	// Single git ls-tree call for all files at once
	args := []string{"ls-tree", commitHash, "--"}
	args = append(args, filePaths...)
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = repoDir

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("git ls-tree failed: %w: %s", err, strings.TrimSpace(stderr.String()))
	}

	// Parse ls-tree output: "<mode> <type> <hash>\t<path>" per line
	// Build sorted filepath:blobhash pairs
	blobMap := make(map[string]string) // path -> blob hash
	for _, line := range strings.Split(strings.TrimSpace(stdout.String()), "\n") {
		if line == "" {
			continue
		}
		// Split on tab to separate metadata from path
		tabIdx := strings.IndexByte(line, '\t')
		if tabIdx == -1 {
			continue
		}
		meta := line[:tabIdx]
		path := line[tabIdx+1:]
		fields := strings.Fields(meta)
		if len(fields) < 3 {
			continue
		}
		blobMap[path] = fields[2]
	}

	// Sort file paths and build pairs
	sorted := make([]string, len(filePaths))
	copy(sorted, filePaths)
	sort.Strings(sorted)

	var pairs []string
	for _, fp := range sorted {
		if blobHash, ok := blobMap[fp]; ok {
			pairs = append(pairs, fp+":"+blobHash)
		}
		// Files not in the tree (deleted) are silently skipped
	}

	if len(pairs) == 0 {
		return "", nil
	}

	h := sha256.Sum256([]byte(strings.Join(pairs, "\n")))
	return fmt.Sprintf("%x", h), nil
}

